.nav { background: var(--panel); border-bottom: 1px solid var(--border); }
.nav nav {
  max-width: 880px;
  margin: 0 auto;
  padding: 0.75rem 1rem;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1rem;
  align-items: center;
}
.nav nav a { color: var(--text); }
.nav nav a:hover { color: var(--accent); text-decoration: none; }
.nav nav p { margin: 0; color: var(--muted); }

main {
  max-width: 880px;
  margin: 0 auto;
  padding: 1.5rem 1rem 3rem;
}

.panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 1rem 1.25rem;
  margin-bottom: 1.25rem;
}
.panel h2 { margin-top: 0; }

.skip-link {
  position: absolute;
  left: -9999px;
  top: auto;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
}
.skip-link:focus {
  left: 0;
  top: 0;
  width: auto;
  height: auto;
  padding: 0.5rem 1rem;
  background: var(--bg);
  color: var(--text);
  border: 2px solid var(--accent);
  border-radius: 0 0 6px 0;
  z-index: 1000;
  clip: auto;
  overflow: visible;
  white-space: nowrap;
}

.copy-button {
  background: var(--panel-2);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 0.25rem 0.6rem;
  font-size: 0.85rem;
  cursor: pointer;
  margin-left: 0.5rem;
}
.copy-button:hover { border-color: var(--accent); }
.copy-button:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

ul { padding-left: 1.25rem; }
li { margin: 0.35rem 0; }

.wake-past { color: var(--muted); }
.wake-current { color: var(--warn); font-weight: 600; }
.wake-next { color: var(--accent); font-weight: 600; }

.countdown-container { display: flex; align-items: center; gap: 1rem; flex-wrap: wrap; }
.countdown {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 1.5rem;
  letter-spacing: 0.05em;
}
.progress-bar {
  flex: 1;
  min-width: 120px;
  height: 6px;
  background: var(--panel-2);
  border-radius: 3px;
  overflow: hidden;
}
.progress-fill { height: 100%; width: 0%; background: var(--accent); transition: width 1s linear; }

.footer { border-top: 1px solid var(--border); background: var(--panel); }
.footer nav {
  max-width: 880px;
  margin: 0 auto;
  padding: 0.75rem 1rem;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1rem;
  align-items: center;
}
.footer nav a { color: var(--text); }
.footer nav a:hover { color: var(--accent); text-decoration: none; }
.footer nav p { margin: 0; color: var(--muted); }

code {
  background: var(--panel-2);
  padding: 0.1rem 0.35rem;
  border-radius: 4px;
  font-size: 0.9em;
}

.promise { color: var(--muted); font-style: italic; }

@media (prefers-reduced-motion: reduce) {
  * { animation: none !important; transition: none !important; }
  .progress-fill { transition: none; }
}

@media (max-width: 560px) {
  .nav nav, .footer nav { flex-direction: column; align-items: flex-start; }
  .countdown { font-size: 1.2rem; }
}
